n41968.content:
\begin{definition}
    \label{MyNat}
    \lean{MyNat}
    \leanok
    We define $\mathrm{MyNat}$ as the inductive type with two constructors:
    \begin{itemize}
        \item a term $0$ (called \texttt{zero});
        \item for every $n \in \mathrm{MyNat}$, a term $\mathrm{succ}(n)$ (the \emph{successor} of $n$).
    \end{itemize}
    In other words, every natural number is obtained from $0$ by applying the successor function a
    finite number of times. We write $1$ for $\mathrm{succ}(0)$.
\end{definition}

n41969.content:
\begin{definition}
    \label{MyNat.add}
    \lean{MyNat.add}
    \uses{MyNat}
    \leanok
    We define \emph{addition} on $\mathrm{MyNat}$ by recursion on the second argument:
    \[
    a + 0 = a, \qquad a + \mathrm{succ}(b) = \mathrm{succ}(a + b).
    \]
\end{definition}

n41970.content:
\begin{definition}
    \label{MyNat.mul}
    \lean{MyNat.mul}
    \uses{MyNat.add}
    \leanok
    We define \emph{multiplication} on $\mathrm{MyNat}$ by recursion on the second argument:
    \[
    a * 0 = 0, \qquad a * \mathrm{succ}(b) = a * b + a.
    \]
\end{definition}

n41971.content:
\begin{lemma}
    \label{MyNat.zero_add}
    \lean{MyNat.zero_add}
    \leanok
    For all $a$ in $\mathrm{MyNat}$ we have $0 + a = a$.
\end{lemma}

n41974.content:
\begin{proof}
    \uses{MyNat.add}
    \leanok
    By induction on the last variable.
\end{proof}

n41977.content:
\begin{lemma}
    \label{MyNat.left_distrib}
    \lean{MyNat.left_distrib}
    \leanok
    For all $a$, $b$ and $c$ in $\mathrm{MyNat}$ we have $a * (b + c) = a * b + a * c$.
\end{lemma}

n41978.content:
\begin{proof}
    \uses{MyNat.add, MyNat.mul, MyNat.add_assoc, MyNat.add_comm}
    \leanok
    By induction on $c$.
\end{proof}

n41979.content:
\begin{lemma}
    \label{MyNat.right_distrib}
    \lean{MyNat.right_distrib}
    \leanok
    For all $a$, $b$ and $c$ in $\mathrm{MyNat}$ we have $(a + b) * c = a * c + b * c$.
\end{lemma}

n41980.content:
\begin{proof}
    \uses{MyNat.add, MyNat.mul, MyNat.add_assoc, MyNat.add_comm}
    \leanok
    By induction on $c$.
\end{proof}

n41982.content:
\begin{proof}
    \uses{MyNat.mul, MyNat.left_distrib}
    \leanok
    By induction, using left distributivity.
\end{proof}

n41985.content:
\begin{lemma}
    \label{MyNat.one_mul}
    \lean{MyNat.one_mul}
    \leanok
    For all $a$ in $\mathrm{MyNat}$ we have $1 * a = a$.
\end{lemma}

n41987.content:
\begin{proposition}
    \label{MyNat.instCommSemiring}
    \lean{MyNat.instCommSemiring}
    \leanok
    $\mathrm{MyNat}$ with addition and multiplication is a commutative semiring.
\end{proposition}

n41988.content:
\begin{proof}
    \uses{MyNat.add, MyNat.mul, MyNat.zero_add, MyNat.add_assoc, MyNat.add_comm,
    MyNat.left_distrib, MyNat.right_distrib, MyNat.mul_assoc, MyNat.mul_comm, MyNat.one_mul}
    \leanok
    We collect all the lemmas above: addition is associative and commutative with neutral element
    $0$, multiplication is associative and commutative with neutral element $1$, multiplication
    distributes over addition and $0$ is absorbing for multiplication.
\end{proof}

n41990.content:
\begin{proof}
    \uses{MyNat}
    \leanok
    The constructors $\mathrm{zero}$ and $\mathrm{succ}$ are distinct, and $1 = \mathrm{succ}(0)$.
\end{proof}

n41991.content:
\begin{lemma}
    \label{MyNat.mul_ne_zero}
    \lean{MyNat.mul_ne_zero}
    \leanok
    Let $a$ and $b$ in $\mathrm{MyNat}$ be such that $a \neq 0$ and $b \neq 0$. Then $a * b \neq 0$.
\end{lemma}

n41992.content:
\begin{proof}
    \uses{MyNat.mul}
    \leanok
    If $a \neq 0$ and $b \neq 0$ we can write $a = \mathrm{succ}(a')$ and $b = \mathrm{succ}(b')$, and
    then $a * b = \mathrm{succ}(a' * b' + a' + b')$ is a successor, hence nonzero.
\end{proof}

n41993.content:
\begin{definition}
    \label{MyNat.le}
    \lean{MyNat.le}
    \uses{MyNat.add}
    \leanok
    Let $a$ and $b$ in $\mathrm{MyNat}$. We write $a \leq b$ if there exists a natural number $x$ such that
    \[
    b = a + x.
    \]
\end{definition}

n41997.content:
\begin{proof}
    \uses{MyNat.le, MyNat.add_assoc}
    \leanok
    If $b = a + x$ and $c = b + y$ then $c = a + (x + y)$.
\end{proof}

n41999.content:
\begin{proof}
    \uses{MyNat.le}
    \leanok
    If $b = a + x$ and $a = b + y$ then $a = a + (x + y)$, so $x + y = 0$ and hence $x = y = 0$,
    giving $a = b$.
\end{proof}

n42001.content:
\begin{proof}
    \uses{MyNat.le}
    \leanok
    By induction one shows that for all $a$ and $b$ either $a \leq b$ or $b \leq a$.
\end{proof}

n42002.content:
\begin{lemma}
    \label{MyNat.linearOrder}
    \lean{MyNat.linearOrder}
    \leanok
    We have that $\mathrm{MyNat}$ with $\leq$ is a \emph{linear order}.
\end{lemma}

n42003.content:
\begin{proof}
    \uses{MyNat.le_refl, MyNat.le_trans, MyNat.le_antisymm, MyNat.le_total}
    \leanok
    Clear from the lemmas above.
\end{proof}

n42004.content:
\begin{lemma}
    \label{MyNat.add_le_add_left}
    \lean{MyNat.add_le_add_left}
    \leanok
    Let $a$, $b$ and $c$ in $\mathrm{MyNat}$ be such that $a \leq b$. Then $a + c \leq b + c$.
\end{lemma}

n42005.content:
\begin{proof}
    \uses{MyNat.le, MyNat.add}
    \leanok
    Let $x$ be such that $b = a + x$. The same $x$ shows that $a + c \leq b + c$.
\end{proof}

n42006.content:
\begin{lemma}
    \label{MyNat.mul_lt_mul_of_pos_left}
    \lean{MyNat.mul_lt_mul_of_pos_left}
    \leanok
    Let $a$, $b$ and $c$ in $\mathrm{MyNat}$ be such that $0 < c$ and $a < b$. Then $c * a < c * b$.
\end{lemma}

n42007.content:
\begin{proof}
    \uses{MyNat.le, MyNat.mul, MyNat.left_distrib, MyNat.mul_ne_zero}
    \leanok
    Write $b = a + x$ with $x \neq 0$. Then $c * b = c * a + c * x$ with $c * x \neq 0$, so
    $c * a < c * b$.
\end{proof}

n42008.content:
\begin{lemma}
    \label{MyNat.mul_lt_mul_of_pos_right}
    \lean{MyNat.mul_lt_mul_of_pos_right}
    \leanok
    Let $a$, $b$ and $c$ in $\mathrm{MyNat}$ be such that $0 < c$ and $a < b$. Then $a * c < b * c$.
\end{lemma}

n42009.content:
\begin{proof}
    \uses{MyNat.mul_lt_mul_of_pos_left, MyNat.mul_comm}
    \leanok
    Identical to the previous lemma using commutativity of multiplication.
\end{proof}

n42011.content:
\begin{definition}
    \label{MyPreint.R}
    \lean{MyPreint.R}
    \leanok
    \uses{MyPreint}
We define a relation $R$ on $\mathrm{MyPreint}$ as follows: $(a,b)$ and $(c, d)$ are related if and only if
\[
a + d = b + c
\]
\end{definition}

n42013.content:
\begin{proof}
    \leanok
    \uses{MyPreint.R}
    This follows by commutativity of addition in $\mathrm{MyNat}$.
\end{proof}

n42015.content:
\begin{proof}
    \leanok
    \uses{MyPreint.R}
    This follows by commutativity of addition in $\mathrm{MyNat}$.
\end{proof}

n42018.content:
\begin{lemma}
    \label{MyPreint.R_equiv}
    \lean{MyPreint.R_equiv}
    \leanok
We have that $R$ is an equivalence relation. From now on, we will write $x \approx y$ for
$x R y$.
\end{lemma}

n42019.content:
\begin{proof}
    \leanok
    \uses{MyPreint.R_refl, MyPreint.R_symm, MyPreint.R_trans}
Clear from Lemma~\ref{MyPreint.R_refl}, Lemma~\ref{MyPreint.R_symm} and Lemma~\ref{MyPreint.R_trans}.
\end{proof}

n42020.content:
\begin{definition}
    \label{MyPreint.neg}
    \lean{MyPreint.neg}
    \leanok
    \uses{MyPreint.R}
We define an operation, called \emph{negation} on $\mathrm{MyPreint}$ as follows: the negation of $x = (a,b)$ is
$(b,a)$:
\[
-x = -(a,b) = (b,a)
\]
\end{definition}

n42022.content:
\begin{proof}
\uses{MyPreint.neg}
\leanok
Let $x = (a,b)$ and $x' = (a',b')$, so by assumption $a + b' = b + a'$. By definition we have
\[
-x=-(a,b)=(b,a) \mbox{ and } -x'=-(a',b')=(b',a')
\]
We need to show $b+a'=b'+a$, which follows immediately from $a + b' = b + a'$.
\end{proof}

n42023.content:
\begin{definition}
    \label{MyPreint.add}
    \lean{MyPreint.add}
    \leanok
    \uses{MyPreint.R}
We define an operation, called \emph{addition} on $\mathrm{MyPreint}$ as follows: the addition of $x = (a,b)$
and $y = (c, d)$ is
\[
x + y = (a,b) + (c,d) = (a+c, b + d)
\]
\end{definition}

n42024.content:
\begin{lemma}
    \label{MyPreint.add_quotient}
    \lean{MyPreint.add_quotient}
    \leanok
If $x \approx x'$ and $y \approx y'$, then $x + y \approx x' + y'$.
\end{lemma}

n42026.content:
\begin{definition}
    \label{MyPreint.mul}
    \lean{MyPreint.mul}
    \leanok
    \uses{MyPreint.R}
We define an operation, called \emph{multiplication} on $\mathrm{MyPreint}$ as follows: the multiplication of $x = (a,b)$ and $y = (c, d)$ is
\[
x * y = (a,b) * (c,d) = (a*c+b*d, a*d+b*c)
\]
\end{definition}

n42027.content:
\begin{lemma}
    \label{MyPreint.mul_quotient}
    \lean{MyPreint.mul_quotient}
    \leanok
If $x \approx x'$ and $y \approx y'$, then $x * y \approx x' * y'$.
\end{lemma}

n42029.content:
\begin{definition}
    \label{MyInt}
    \lean{MyInt}
    \leanok
    \uses{MyPreint.R_equiv}
    We define our integers $\mathrm{MyInt}$ as
\[
\mathrm{MyInt}= \mathrm{MyPreint}\, / \approx
\]
We will write $⟦ (a, b) ⟧$ for the class of $(a,b)$.
\end{definition}

n42030.content:
\begin{definition}
    \label{MyInt.zero}
    \lean{MyInt.zero}
    \uses{MyPreint.R_equiv}
    \leanok
We define the zero of $\mathrm{MyInt}$, denoted $0$ as the class of $(0,0)$.
\end{definition}

n42031.content:
\begin{definition}
    \label{MyInt.one}
    \lean{MyInt.one}
    \uses{MyPreint.R_equiv}
    \leanok
We define the one of $\mathrm{MyInt}$, denoted $1$ as the class of $(1,0)$.
\end{definition}

n42032.content:
\begin{definition}
    \label{MyInt.neg}
    \lean{MyInt.neg}
    \uses{MyPreint.R_equiv, MyPreint.neg_quotient}
    \leanok
We define the negation of $x = ⟦ (a, b) ⟧$ in $\mathrm{MyInt}$ as
\[
-x = ⟦ -(a, b) ⟧
\]
Thanks to Lemma~\ref{MyPreint.neg_quotient} this is well defined.
\end{definition}

n42033.content:
\begin{definition}
    \label{MyInt.add}
    \lean{MyInt.add}
    \uses{MyPreint.R_equiv, MyPreint.add_quotient}
    \leanok
We define the addition of $x = ⟦ (a, b) ⟧$ and $y = ⟦ (c, d) ⟧$ in $\mathrm{MyInt}$ as
\[
x + y = ⟦ (a, b)+(c,d) ⟧
\]
Thanks to Lemma~\ref{MyPreint.add_quotient} this is well defined.
\end{definition}

n42034.content:
\begin{definition}
    \label{MyInt.mul}
    \lean{MyInt.mul}
    \uses{MyPreint.R_equiv, MyPreint.mul_quotient}
    \leanok
We define the multiplication of $x = ⟦ (a, b) ⟧$ and $y = ⟦ (c, d) ⟧$ in $\mathrm{MyInt}$ as
\[
x * y = ⟦ (a, b)*(c,d) ⟧
\]
Thanks to Lemma~\ref{MyPreint.mul_quotient} this is well defined.
\end{definition}

n42037.content:
\begin{proposition}
    \label{MyInt.commRing}
    \lean{MyInt.commRing}
    \leanok
    $\mathrm{MyInt}$ with addition and multiplication is a commutative ring.
\end{proposition}

n42038.content:
\begin{proof}
    \uses{MyInt.add, MyInt.mul, MyInt.zero, MyInt.one}
    \leanok
    We have to prove various properties, namely:
    \begin{itemize}
        \item addition is associative (already done in Lemma~\ref{MyInt.add_assoc})
        \item $0$ works as neutral element for addition (on both sides)
        \item existence of an inverse for addition (we prove that $x + (-x) = (-x) + x = 0$)
        \item addition is commutative
        \item left and right distributivity of multiplication with respect to addition
        \item associativity of multiplication
        \item $1$ works as neutral element for multiplication (on both sides)
    \end{itemize}
    All the proofs are essentially identical to the proof of Lemma~\ref{MyInt.add_assoc} above.
\end{proof}

n42040.content:
\begin{proof}
    \leanok
    \uses{MyInt.zero, MyInt.one}
    If $0 = 1$ by definition we would have $⟦ (0,0) ⟧ = ⟦ (1,0) ⟧$
    so $0+1=0+0$ in $\mathrm{MyNat}$, that is absurd.
\end{proof}

n42041.content:
\begin{lemma}
    \label{MyInt.mul_ne_zero}
    \lean{MyInt.mul_ne_zero}
    \leanok
Let $x$ and $y$ in $\mathrm{MyInt}$ such that $x \neq 0$ and $y \neq 0$. Then $x*y \neq 0$.
\end{lemma}

n42042.content:
\begin{proof}
    \leanok
    \uses{MyInt.zero, MyInt.mul}
    It is enough to prove that, for all $a$, $b$, $c$ and $d$ in $\mathrm{MyNat}$ such that $a \neq b$ and $c \neq d$ we have $a*c+b*d\neq a*d+b*c$. If this is not the case we must have $a = b$ or $c = d$. (Can you see how to prove this in $\mathrm{MyNat}$? You cannot use subtraction!) and we are done.
\end{proof}

n42043.content:
\begin{lemma}
    \label{MyInt.eq_of_mul_eq_mul_right}
    \lean{MyInt.eq_of_mul_eq_mul_right}
    \leanok
Let $x$, $y$ and $z$ in $\mathrm{MyInt}$ such that $x \neq 0$ and $y * x = z * x$. Then $y = z$.
\end{lemma}

n42044.content:
\begin{proof}
    \leanok
    \uses{MyInt.mul_ne_zero}
We have $0 = y*x-z*x=(y-z)*x$. Since $x \neq 0$ we have by Lemma~\ref{MyInt.mul_ne_zero} that $y-z=0$ and hence $y=z$.
\end{proof}

n42045.content:
\begin{definition}
    \label{MyInt.i}
    \lean{MyInt.i}
    \uses{MyInt}
    \leanok
    We define a map
\begin{gather*}
    i \colon \mathrm{MyNat}\to \mathrm{MyInt}\\
    n \mapsto ⟦ (n,0) ⟧
\end{gather*}
\end{definition}

n42050.content:
\begin{lemma}
    \label{MyInt.i_add}
    \lean{MyInt.i_add}
    \leanok
For all $a$ and $b$ in $\mathrm{MyNat}$ we have that
\[
i(a+b) = i(a) + i(b)
\]
\end{lemma}

n42051.content:
\begin{proof}
    \uses{MyInt.add, MyInt.i}
    \leanok
    We have $i(a+b) = ⟦ (a+b, 0) ⟧$, $i(a) = ⟦ (a, 0) ⟧$ and
    $i(b) = ⟦ (b, 0) ⟧$, so we need to prove that
\[
⟦ (a+b, 0) ⟧ = ⟦ (a, 0) ⟧ + ⟦ (b, 0) ⟧
\]
that is obvious from the definition.
\end{proof}

n42052.content:
\begin{lemma}
    \label{MyInt.i_mul}
    \lean{MyInt.i_mul}
    \leanok
For all $a$ and $b$ in $\mathrm{MyNat}$ we have that
\[
i(a*b) = i(a) * i(b)
\]
\end{lemma}

n42055.content:
\begin{proof}
    \uses{MyInt.i}
    \leanok
    Let $a$ and $b$ such that $i(a)=i(b)$. This means $⟦ (a,0) ⟧ = ⟦ (b,0) ⟧$ so $a + 0 = 0 + b$ and hence $a = b$.
\end{proof}

n42056.content:
\begin{definition}
    \label{MyInt.le}
    \lean{MyInt.le}
    \uses{MyInt.i, MyInt.add}
    \leanok
Let $x$ and $y$ in $\mathrm{MyInt}$. We write $x \leq y$ if there exist a natural number $n$ such that
\[
y = x + i(n)
\]
\end{definition}

n42060.content:
\begin{proof}
    \uses{MyInt.le}
    \leanok
    Let $x$, $y$ and $z$ such that $x \leq y$ and $y \leq z$. It follows that there exist $p$ and $q$
    such that $y = x + i(p)$ and $z = y + i(q)$. One can now take $p+q$ to show that $x \leq z$.
\end{proof}

n42063.content:
\begin{lemma}
    \label{MyInt.le_total}
    \lean{MyInt.le_total}
    \leanok
    The order $\leq$ on $\mathrm{MyInt}$ is a total order.
\end{lemma}

n42065.content:
\begin{lemma}
    \label{MyInt.linearOrder}
    \lean{MyInt.linearOrder}
    \leanok
    We have that $\mathrm{MyInt}$ with $\leq$ is a \emph{linear order}
\end{lemma}

n42068.content:
\begin{proof}
    \uses{MyInt.zero, MyInt.one, MyInt.le, MyInt.add}
    \leanok
    We use $1$ (as natural number). We need to prove that $0 + i(1) = 1$. Unravelling the definitions
    this is obvious.
\end{proof}

n42069.content:
\begin{lemma}
    \label{MyInt.i_le_iff}
    \lean{MyInt.i_le_iff}
    \leanok
    Given two natural numbers $a$ and $b$, we have $i(a) \leq i(b)$ if and only if $a \leq b$.
\end{lemma}

n42070.content:
\begin{proof}
    \uses{MyInt.i, MyInt.i_add, MyInt.i_injective}
    \leanok
    \begin{itemize}
        \item If $i(a) \leq i(b)$, let $n$ be such that $i(b) = i(a)+i(n)=i(a+n)$. We obtain $b = a + n$ by injectivity of $i$ and so $a \leq b$.
        \item If $a \leq b$, let $k$ be such that $b = a + k$. We can use $k$ to show that $i(a) \leq i(b)$.
    \end{itemize}
\end{proof}

n42071.content:
\begin{lemma}
    \label{MyInt.add_le_add_left}
    \lean{MyInt.add_le_add_left}
    \leanok
    Let $x$, $y$ and $z$ in $\mathrm{MyInt}$ be such that $x \leq y$. Then $x + z \leq y + z$.
\end{lemma}

n42072.content:
\begin{proof}
    \uses{MyInt.le, MyInt.add}
    \leanok
    Let $n$ be such that $y = x + i(n)$. It's immediate that $n$ also works to show that $x + z \leq y + z$.
\end{proof}

n42073.content:
\begin{lemma}
    \label{MyInt.mul_pos}
    \lean{MyInt.mul_pos}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyInt}$ be such that $0 < x$ and $0 < y$. Then $0 < x * y$.
\end{lemma}

n42074.content:
\begin{proof}
    \leanok
    \uses{MyInt.mul_ne_zero, MyInt.le, MyInt.mul}
    By Lemma~\ref{MyInt.mul_ne_zero} we already know that $x*y \neq 0$, so it is enough to prove that
    $0 \leq x*y$. Since $0 < x$, we have in particular that $0 \leq x$, and let $n$ be such that $x = 0 + i(n)$. Similarly, let $m$ be such that $y = 0 + i(m)$. We have $0 + i(n) = i(n)$ and $0 + i(m) = i(m)$, so we need to prove that $0 \leq i(n)*i(m)$. We do so using $n*m$: we have
    \[
    0+i(n*m)=i(n*m)=i(n)*i(m)
    \]
    as required.
\end{proof}

n42075.content:
\begin{lemma}
    \label{MyInt.archimedean}
    \lean{MyInt.archimedean}
    \leanok
    \uses{MyInt.le, MyInt.i}
    For every $x$ in $\mathrm{MyInt}$ there exists $n$ in $\mathrm{MyNat}$ such that $x \leq i(n)$.
\end{lemma}

n42076.content:
\begin{proof}
    \leanok
    Write $x = ⟦(a,b)⟧$. Then $i(a) = x + i(b)$ in $\mathrm{MyInt}$, so $x \leq i(a)$.
\end{proof}

n42078.content:
\begin{definition}
    \label{MyPrerat.R}
    \lean{MyPrerat.R}
    \leanok
    \uses{MyPrerat}
We define a relation $R$ on $\mathrm{MyPrerat}$ as follows: $(a,b)$ and $(c, d)$ are related if and only if
\[
a * d = b * c
\]
\end{definition}

n42085.content:
\begin{lemma}
    \label{MyPrerat.R_equiv}
    \lean{MyPrerat.R_equiv}
    \leanok
We have that $R$ is an equivalence relation. From now on, we will write $x \approx y$ for
$x R y$.
\end{lemma}

n42086.content:
\begin{proof}
    \leanok
    \uses{MyPrerat.R_refl, MyPrerat.R_symm, MyPrerat.R_trans}
Clear from Lemma~\ref{MyPrerat.R_refl}, Lemma~\ref{MyPrerat.R_symm} and Lemma~\ref{MyPrerat.R_trans}.
\end{proof}

n42087.content:
\begin{definition}
    \label{MyPrerat.neg}
    \lean{MyPrerat.neg}
    \leanok
    \uses{MyPrerat.R}
We define an operation, called \emph{negation} on $\mathrm{MyPrerat}$ as follows: the negation of $x = (a,b)$ is
$(-a,b)$:
\[
-x = -(a,b) = (-a,b)
\]
Note that it is automatically well defined (meaning that second component of $(-a,b)$ is different from $0$).
\end{definition}

n42090.content:
\begin{definition}
    \label{MyPrerat.add}
    \lean{MyPrerat.add}
    \leanok
    \uses{MyPrerat.R}
We define an operation, called \emph{addition} on $\mathrm{MyPrerat}$ as follows: the addition of $x = (a,b)$
and $y = (c, d)$ is
\[
x + y = (a,b) + (c,d) = (a * d + b * c, b*d)
\]
Do you see why it is well defined?
\end{definition}

n42091.content:
\begin{lemma}
    \label{MyPrerat.add_quotient}
    \lean{MyPrerat.add_quotient}
    \leanok
If $x \approx x'$ and $y \approx y'$, then $x + y \approx x' + y'$.
\end{lemma}

n42093.content:
\begin{definition}
    \label{MyPrerat.mul}
    \lean{MyPrerat.mul}
    \leanok
    \uses{MyPrerat.R}
We define an operation, called \emph{multiplication} on $\mathrm{MyPrerat}$ as follows: the multiplication of $x = (a,b)$ and $y = (c, d)$ is
\[
x * y = (a,b) * (c,d) = (a*c, b*d)
\]
\end{definition}

n42094.content:
\begin{lemma}
    \label{MyPrerat.mul_quotient}
    \lean{MyPrerat.mul_quotient}
    \leanok
If $x \approx x'$ and $y \approx y'$, then $x * y \approx x' * y'$.
\end{lemma}

n42096.content:
\begin{definition}
    \label{MyPrerat.inv}
    \lean{MyPrerat.inv}
    \leanok
    \uses{MyPrerat.R}
We define an operation, called \emph{inversion} on $\mathrm{MyPrerat}$ as follows: the inverse of $x = (a,b)$ is:
\[
\mbox{if } a \neq 0 \mbox{ then } x^{-1} = (b, a), \mbox{ otherwise } x^{-1} = (0, 1)
\]
Note that $x^{-1}$ is \emph{always} defined!
\end{definition}

n42099.content:
\begin{definition}
    \label{MyRat}
    \lean{MyRat}
    \leanok
    \uses{MyPrerat.R_equiv}
    We define our rationals $\mathrm{MyRat}$ as
\[
\mathrm{MyRat}= \mathrm{MyPrerat}\, / \approx
\]
We will write $⟦ (a, b) ⟧$ for the class of $(a,b)$.
\end{definition}

n42100.content:
\begin{definition}
    \label{MyRat.zero}
    \lean{MyRat.zero}
    \uses{MyPrerat.R_equiv}
    \leanok
We define the zero of $\mathrm{MyRat}$, denoted $0$ as the class of $(0,1)$ (note that $1 \neq 0$ in $\mathrm{MyInt}$).
\end{definition}

n42101.content:
\begin{definition}
    \label{MyRat.one}
    \lean{MyRat.one}
    \uses{MyPrerat.R_equiv}
    \leanok
We define the one of $\mathrm{MyRat}$, denoted $1$ as the class of $(1,1)$ (note that $1 \neq 0$ in $\mathrm{MyInt}$).
\end{definition}

n42102.content:
\begin{definition}
    \label{MyRat.neg}
    \lean{MyRat.neg}
    \uses{MyPrerat.R_equiv, MyPrerat.neg_quotient}
    \leanok
We define the negation of $x = ⟦ (a, b) ⟧$ in $\mathrm{MyRat}$ as
\[
-x = ⟦ -(a, b) ⟧
\]
Thanks to Lemma~\ref{MyPrerat.neg_quotient} this is well defined.
\end{definition}

n42103.content:
\begin{definition}
    \label{MyRat.add}
    \lean{MyRat.add}
    \uses{MyPrerat.R_equiv, MyPrerat.add_quotient}
    \leanok
We define the addition of $x = ⟦ (a, b) ⟧$ and $y = ⟦ (c, d) ⟧$ in $\mathrm{MyRat}$ as
\[
x + y = ⟦ (a,b)+(c,d) ⟧
\]
Thanks to Lemma~\ref{MyPrerat.add_quotient} this is well defined.
\end{definition}

n42104.content:
\begin{definition}
    \label{MyRat.mul}
    \lean{MyRat.mul}
    \uses{MyPrerat.R_equiv, MyPrerat.mul_quotient}
    \leanok
We define the multiplication of $x = ⟦ (a, b) ⟧$ and $y = ⟦ (c, d) ⟧$ in $\mathrm{MyRat}$ as
\[
x * y = ⟦ (a, b)*(c,d) ⟧
\]
Thanks to Lemma~\ref{MyPrerat.mul_quotient} this is well defined.
\end{definition}

n42105.content:
\begin{definition}
    \label{MyRat.inv}
    \lean{MyRat.inv}
    \uses{MyPrerat.R_equiv, MyPrerat.inv_quotient}
    \leanok
We define the inverse of $x = ⟦ (a, b) ⟧$ in $\mathrm{MyRat}$ as
\[
x^{-1} = ⟦ (a, b)^{-1} ⟧
\]
Thanks to Lemma~\ref{MyPrerat.inv_quotient} this is well defined.
\end{definition}

n42106.content:
\begin{proposition}
    \label{MyRat.commRing}
    \lean{MyRat.commRing}
    \leanok
    $\mathrm{MyRat}$ with addition and multiplication is a commutative ring.
\end{proposition}

n42107.content:
\begin{proof}
    \uses{MyRat.add, MyRat.mul, MyRat.zero, MyRat.one}
    \leanok
    We have to prove various properties, namely:
    \begin{itemize}
        \item addition is associative
        \item $0$ works as neutral element for addition (on both sides)
        \item existence of an inverse for addition (we prove that $x + (-x) = (-x) + x = 0$)
        \item addition is commutative
        \item left and right distributivity of multiplication with respect to addition
        \item associativity of multiplication
        \item $1$ works as neutral element for multiplication (on both sides)
    \end{itemize}
    All the proofs are essentially identical, going to $\mathrm{MyInt}$, unravelling the definition and then
    checking the equality holds in $\mathrm{MyInt}$.
\end{proof}

n42109.content:
\begin{proof}
    \leanok
    \uses{MyRat.zero, MyRat.one}
    If $0 = 1$ by definition we would have $⟦ (0,1) ⟧ = ⟦ (1,1) ⟧$
    so $0*1=1*0$ in $\mathrm{MyInt}$, that is absurd.
\end{proof}

n42111.content:
\begin{proof}
    \leanok
    \uses{MyRat.inv, MyRat.mul}
    Let $x = ⟦ (a,b) ⟧$, with $b \neq 0$. Since $x \neq 0$ we have $a \neq 0$ and so
    $x^{-1} = ⟦ (b,a) ⟧$. The lemma follows by definition of multiplication.
\end{proof}

n42112.content:
\begin{proposition}
    \label{MyRat.field}
    \lean{MyRat.field}
    \leanok
    $\mathrm{MyRat}$ with addition and multiplication is a field.
\end{proposition}

n42114.content:
\begin{definition}
    \label{MyRat.i}
    \lean{MyRat.i}
    \uses{MyRat}
    \leanok
    We define a map
\begin{gather*}
    i \colon \mathrm{MyNat}\to \mathrm{MyRat}\\
    n \mapsto ⟦ (\mathrm{MyInt}.i n,1) ⟧
\end{gather*}
\end{definition}

n42119.content:
\begin{lemma}
    \label{MyRat.i_add}
    \lean{MyRat.i_add}
    \leanok
For all $a$ and $b$ in $\mathrm{MyNat}$ we have that
\[
i(a+b) = i(a) + i(b)
\]
\end{lemma}

n42120.content:
\begin{proof}
    \uses{MyRat.add, MyRat.i}
    \leanok
    We have $i(a+b) = ⟦ (\mathrm{MyInt}.i (a+b), 1) ⟧ = ⟦ (\mathrm{MyInt}.i (a), 1) + (\mathrm{MyInt}.i (b), 1) ⟧$, $i(a) = ⟦ (\mathrm{MyInt}.i(a), 1) ⟧$ and
    $i(b) = ⟦ (\mathrm{MyInt}.i (b), 1) ⟧$, so we need to prove that
\[
⟦ (\mathrm{MyInt}.i (a), 1) + (\mathrm{MyInt}.i (b), 1) ⟧ = ⟦ (\mathrm{MyInt}.i (a), 1) ⟧ + ⟦ (\mathrm{MyInt}.i (b), 1) ⟧
\]
that is obvious from the definition.
\end{proof}

n42121.content:
\begin{lemma}
    \label{MyRat.i_mul}
    \lean{MyRat.i_mul}
    \leanok
For all $a$ and $b$ in $\mathrm{MyNat}$ we have that
\[
i(a*b) = i(a) * i(b)
\]
\end{lemma}

n42122.content:
\begin{proof}
    \uses{MyRat.mul, MyRat.i}
    \leanok
Similar to the proof of Lemma~\ref{MyRat.i_add}.
\end{proof}

n42124.content:
\begin{proof}
    \uses{MyRat.i}
    \leanok
    Let $a$ and $b$ be such that $i(a)=i(b)$. This means
    $⟦ (\mathrm{MyInt}.i a,1) ⟧ = ⟦ (\mathrm{MyInt}.i b,1) ⟧$, so
    $(\mathrm{MyInt}.i a) * 1 = 1 * (\mathrm{MyInt}.i b)$. Hence $\mathrm{MyInt}.i a = \mathrm{MyInt}.i b$, and injectivity
    of $\mathrm{MyInt}.i$ gives $a = b$.
\end{proof}

n42125.content:
\begin{definition}
    \label{MyRat.j}
    \lean{MyRat.j}
    \uses{MyRat}
    \leanok
    We define a map
\begin{gather*}
    j \colon \mathrm{MyInt}\to \mathrm{MyRat}\\
    n \mapsto ⟦ (n,1) ⟧
\end{gather*}
\end{definition}

n42130.content:
\begin{lemma}
    \label{MyRat.j_add}
    \lean{MyRat.j_add}
    \leanok
For all $a$ and $b$ in $\mathrm{MyInt}$ we have that
\[
j(a+b) = j(a) + j(b)
\]
\end{lemma}

n42132.content:
\begin{lemma}
    \label{MyRat.j_mul}
    \lean{MyRat.j_mul}
    \leanok
For all $a$ and $b$ in $\mathrm{MyInt}$ we have that
\[
j(a*b) = j(a) * j(b)
\]
\end{lemma}

n42136.content:
\begin{lemma}
    \label{MyRat.j_comp_eq_i}
    \lean{MyRat.j_comp_eq_i}
    \leanok
    Let $n$ be a natural number. Then $\mathrm{MyRat}.j (\mathrm{MyInt}.i (n)) = \mathrm{MyRat}.i (n)$.
\end{lemma}

n42137.content:
\begin{proof}
    \uses{MyRat.i, MyRat.j}
    \leanok
It follows from unravelling all the definitions.
\end{proof}

n42138.content:
\begin{lemma}
    \label{MyRat.Quotient.mk_def}
    \lean{MyRat.Quotient.mk_def}
    \leanok
    Let $a$ and $b$ be in $\mathrm{MyInt}$ with $b \neq 0$. Then $⟦ (a, b) ⟧ = j(a)*j(b)^{-1}$.
\end{lemma}

n42140.content:
\begin{definition}
    \label{MyRat.IsNonneg}
    \lean{MyRat.IsNonneg}
    \uses{MyRat, MyRat.zero}
    \leanok
Given $x$ in $\mathrm{MyRat}$, we say that $x$ is \emph{nonnegative} if it has a representative with
nonnegative numerator and positive denominator: there exist $a$ and $b$ in $\mathrm{MyInt}$ with
$0 \leq a$ and $0 < b$ such that
\[
x = ⟦(a,b)⟧.
\]
This is the usual condition $0 \leq a/b$ after choosing a positive denominator.
\end{definition}

n42141.content:
\begin{lemma}
    \label{MyRat.zero_nonneg}
    \lean{MyRat.zero_nonneg}
    \uses{MyRat.IsNonneg}
    \leanok
    We have that $0$ in $\mathrm{MyRat}$ is nonnegative.
\end{lemma}

n42143.content:
\begin{lemma}
    \label{MyRat.one_nonneg}
    \lean{MyRat.one_nonneg}
    \uses{MyRat.IsNonneg, MyRat.one}
    \leanok
    We have that $1$ in $\mathrm{MyRat}$ is nonnegative.
\end{lemma}

n42145.content:
\begin{lemma}
    \label{MyRat.nonneg_neg}
    \lean{MyRat.nonneg_neg}
    \uses{MyRat.IsNonneg, MyRat.neg}
    \leanok
    Let $x$ be in $\mathrm{MyRat}$ such that both $x$ and $-x$ are nonnegative. Then $x = 0$.
\end{lemma}

n42146.content:
\begin{proof}
    \leanok
    Unravelling all the definitions we end up with $a$, $b$, $c$ and $d$ in $\mathrm{MyInt}$ such that $0 \leq a$, $0 < b$, $0 \leq c$, $0 < d$ and $-(a*d)=b*c$. This implies $a=0$.
\end{proof}

n42147.content:
\begin{lemma}
    \label{MyRat.nonneg_neg_of_not_nonneg}
    \lean{MyRat.nonneg_neg_of_not_nonneg}
    \uses{MyRat.IsNonneg, MyRat.neg}
    \leanok
    Let $x$ be in $\mathrm{MyRat}$ such that $x$ is not nonnegative. Then $-x$ is nonnegative.
\end{lemma}

n42148.content:
\begin{proof}
    \leanok
    Annoying but easy, left as an exercise.
\end{proof}

n42149.content:
\begin{lemma}
