\end{lemma}

n42166.content:
\begin{lemma}
    \label{MyRat.add_le_add_left}
    \lean{MyRat.add_le_add_left}
    \leanok
    Let $x$, $y$ and $z$ in $\mathrm{MyRat}$ be such that $x \leq y$. Then $x + z \leq y + z$.
\end{lemma}

n42168.content:
\begin{lemma}
    \label{MyRat.mul_nonneg}
    \lean{MyRat.mul_nonneg}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyRat}$ be such that $0 \leq x$ and $0 \leq y$. Then $0 \leq x * y$.
\end{lemma}

n42170.content:
\begin{lemma}
    \label{MyRat.j_le_iff}
    \lean{MyRat.j_le_iff}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyInt}$. We have that $j(x) \leq j(y)$ if and only if $x \leq y$.
