n42173.content:
\begin{proof}
    \uses{MyRat.IsNonneg, MyInt.i_le_iff, MyRat.j_le_iff, MyRat.j_comp_eq_i}
    \leanok
    It follows immediately by Lemma~\ref{MyInt.i_le_iff}, Lemma~\ref{MyRat.j_le_iff} and Lemma~\ref{MyRat.j_comp_eq_i}.
\end{proof}

n42174.content:
\begin{lemma}
    \label{MyRat.le_total}
    \lean{MyRat.le_total}
    \leanok
    The order $\leq$ on $\mathrm{MyRat}$ is a total order.
\end{lemma}

n42176.content:
\begin{lemma}
    \label{MyRat.linearOrder}
    \lean{MyRat.linearOrder}
    \leanok
    We have that $\mathrm{MyRat}$ with $\leq$ is a \emph{linear order}
\end{lemma}

n42177.content:
\begin{proof}
    \uses{MyRat.le_refl, MyRat.le_antisymm, MyRat.le_trans, MyRat.le_total}
    \leanok
    Clear from the lemma above.
\end{proof}

n42178.content:
\begin{lemma}
    \label{MyRat.mul_pos}
    \lean{MyRat.mul_pos}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyRat}$ be such that $0 < x$ and $0 < y$. Then $0 < x * y$.
\end{lemma}

n42180.content:
\begin{lemma}
    \label{MyRat.archimedean}
    \lean{MyRat.archimedean}
    \leanok
    \uses{MyRat.i, MyRat.j_le_iff, MyInt.archimedean}
    For every $x$ in $\mathrm{MyRat}$ there exists $n$ in $\mathrm{MyNat}$ such that $x \leq i(n)$.
\end{lemma}

n42182.content:
\begin{definition}
    \label{IsCauchy}
    \lean{IsCauchy}
    \leanok
    \uses{MyRat}
A sequence $x \colon \mathrm{MyNat}\to \mathrm{MyRat}$ is a \emph{Cauchy sequence} if
\[
\forall \varepsilon > 0, \ \exists N, \ \forall p, q \geq N, \ |x_p - x_q| \leq \varepsilon.
\]
\end{definition}

n42183.content:
\begin{lemma}
    \label{IsCauchy.bounded}
    \lean{IsCauchy.bounded}
    \leanok
    \uses{IsCauchy}
    Every Cauchy sequence $x$ is bounded: there exists $B > 0$ such that $|x_n| \leq B$ for all $n$.
\end{lemma}

n42184.content:
\begin{proof}
    \leanok
    Apply the definition with $\varepsilon = 1$ to get an $N$, and take $B$ to be the maximum of
    $1 + |x_N|$ and the finitely many values $|x_0|, \dots, |x_{N-1}|$.
\end{proof}

n42185.content:
\begin{definition}
    \label{MyPrereal}
    \lean{MyPrereal}
    \leanok
    \uses{IsCauchy}
Let $\mathrm{MyPrereal}$ be the type of Cauchy sequences, that is the subtype of $x \colon \mathrm{MyNat}\to \mathrm{MyRat}$
such that $x$ is a Cauchy sequence.
\end{definition}

n42186.content:
\begin{definition}
    \label{MyPrereal.R}
    \lean{MyPrereal.R}
    \leanok
    \uses{MyPrereal}
We define a relation $R$ on $\mathrm{MyPrereal}$ as follows: $x$ and $y$ are related if and only if
\[
\forall \varepsilon > 0, \ \exists N, \ \forall n \geq N, \ |x_n - y_n| \leq \varepsilon,
\]
in other words if their difference tends to $0$.
\end{definition}

n42192.content:
\begin{proof}
    \leanok
    \uses{MyPrereal.R}
    Exercise, using the triangle inequality and splitting $\varepsilon$ into $\varepsilon/2 +
    \varepsilon/2$.
\end{proof}

n42193.content:
\begin{lemma}
    \label{MyPrereal.R_equiv}
    \lean{MyPrereal.R_equiv}
    \leanok
We have that $R$ is an equivalence relation. From now on, we will write $x \approx y$ for $x R y$.
\end{lemma}

n42194.content:
\begin{proof}
    \leanok
    \uses{MyPrereal.R_refl, MyPrereal.R_symm, MyPrereal.R_trans}
Clear from Lemma~\ref{MyPrereal.R_refl}, Lemma~\ref{MyPrereal.R_symm} and
Lemma~\ref{MyPrereal.R_trans}.
\end{proof}

n42195.content:
\begin{lemma}
    \label{MyPrereal.IsCauchy.const}
    \lean{MyPrereal.IsCauchy.const}
    \leanok
    \uses{IsCauchy}
For any rational $x$, the constant sequence $n \mapsto x$ is a Cauchy sequence.
\end{lemma}

n42197.content:
\begin{definition}
    \label{MyPrereal.zero}
    \lean{MyPrereal.zero}
    \leanok
    \uses{MyPrereal.IsCauchy.const}
We define the zero of $\mathrm{MyPrereal}$ as the constant sequence $0$.
\end{definition}

n42198.content:
\begin{definition}
    \label{MyPrereal.one}
    \lean{MyPrereal.one}
    \leanok
    \uses{MyPrereal.IsCauchy.const}
We define the one of $\mathrm{MyPrereal}$ as the constant sequence $1$.
\end{definition}

n42199.content:
\begin{lemma}
    \label{MyPrereal.IsCauchy.neg}
    \lean{MyPrereal.IsCauchy.neg}
    \leanok
    \uses{IsCauchy}
If $x$ is a Cauchy sequence, then $-x$ (the termwise negation) is a Cauchy sequence. In particular
negation is well defined on $\mathrm{MyPrereal}$.
\end{lemma}

n42203.content:
\begin{lemma}
    \label{MyPrereal.IsCauchy.add}
    \lean{MyPrereal.IsCauchy.add}
    \leanok
    \uses{IsCauchy}
If $x$ and $y$ are Cauchy sequences, then $x + y$ (the termwise sum) is a Cauchy sequence. In
particular addition is well defined on $\mathrm{MyPrereal}$.
\end{lemma}

n42205.content:
\begin{lemma}
    \label{MyPrereal.add_quotient}
    \lean{MyPrereal.add_quotient}
    \leanok
    \uses{MyPrereal.IsCauchy.add}
If $x \approx x'$ and $y \approx y'$, then $x + y \approx x' + y'$.
\end{lemma}

n42207.content:
\begin{lemma}
    \label{MyPrereal.IsCauchy.mul}
    \lean{MyPrereal.IsCauchy.mul}
    \leanok
    \uses{IsCauchy, IsCauchy.bounded}
If $x$ and $y$ are Cauchy sequences, then $x * y$ (the termwise product) is a Cauchy sequence. In
particular multiplication is well defined on $\mathrm{MyPrereal}$.
\end{lemma}

n42208.content:
\begin{proof}
    \leanok
    Write $x_p y_p - x_q y_q = x_p(y_p - y_q) + (x_p - x_q)y_q$ and use that Cauchy sequences are
    bounded (Lemma~\ref{IsCauchy.bounded}).
\end{proof}

n42209.content:
\begin{lemma}
    \label{MyPrereal.mul_quotient}
    \lean{MyPrereal.mul_quotient}
    \leanok
    \uses{MyPrereal.IsCauchy.mul}
If $x \approx x'$ and $y \approx y'$, then $x * y \approx x' * y'$.
\end{lemma}

n42211.content:
\begin{lemma}
    \label{MyPrereal.pos_of_not_equiv_zero}
    \lean{MyPrereal.pos_of_not_equiv_zero}
    \leanok
    \uses{MyPrereal.zero, MyPrereal.R}
Let $x$ be in $\mathrm{MyPrereal}$ with $x \not\approx 0$. Then there exist $\delta > 0$ and $N$ such that
$\delta < |x_n|$ for all $n \geq N$.
\end{lemma}

n42212.content:
\begin{proof}
    \leanok
    Since $x \not\approx 0$ there is some $\varepsilon > 0$ for which the defining condition fails;
    combine this with the Cauchy property to make $|x_n|$ eventually larger than $\delta =
    \varepsilon/2$.
\end{proof}

n42213.content:
\begin{lemma}
    \label{MyPrereal.IsCauchy.inv}
    \lean{MyPrereal.IsCauchy.inv}
    \leanok
    \uses{MyPrereal.pos_of_not_equiv_zero}
Let $x$ be in $\mathrm{MyPrereal}$ with $x \not\approx 0$. Then the termwise inverse $x^{-1}$ is a Cauchy
sequence.
\end{lemma}

n42214.content:
\begin{proof}
    \leanok
    \uses{IsCauchy}
    Using Lemma~\ref{MyPrereal.pos_of_not_equiv_zero} the terms are eventually bounded away from $0$,
    and then $|x_p^{-1} - x_q^{-1}| = |x_p - x_q| / |x_p x_q|$ is controlled.
\end{proof}

n42215.content:
\begin{definition}
    \label{MyPrereal.inv}
    \lean{MyPrereal.inv}
    \leanok
    \uses{MyPrereal.IsCauchy.inv, MyPrereal.zero}
We define the inverse of $x$ in $\mathrm{MyPrereal}$ as the termwise inverse $x^{-1}$ if $x \not\approx 0$,
and as $0$ otherwise. Note that it is \emph{always} defined.
\end{definition}

n42218.content:
\begin{definition}
    \label{MyReal}
    \lean{MyReal}
    \leanok
    \uses{MyPrereal.R_equiv}
    We define our reals $\mathrm{MyReal}$ as
\[
\mathrm{MyReal}= \mathrm{MyPrereal}\, / \approx
\]
We will write $⟦ x ⟧$ for the class of the Cauchy sequence $x$.
\end{definition}

n42219.content:
\begin{definition}
    \label{MyReal.zero}
    \lean{MyReal.zero}
    \leanok
    \uses{MyReal, MyPrereal.zero}
We define the zero of $\mathrm{MyReal}$, denoted $0$, as the class of the zero of $\mathrm{MyPrereal}$.
\end{definition}

n42220.content:
\begin{definition}
    \label{MyReal.one}
    \lean{MyReal.one}
    \leanok
    \uses{MyReal, MyPrereal.one}
We define the one of $\mathrm{MyReal}$, denoted $1$, as the class of the one of $\mathrm{MyPrereal}$.
\end{definition}

n42221.content:
\begin{definition}
    \label{MyReal.neg}
    \lean{MyReal.neg}
    \leanok
    \uses{MyReal, MyPrereal.neg_quotient}
We define the negation of $⟦ x ⟧$ in $\mathrm{MyReal}$ as $⟦ -x ⟧$. Thanks to
Lemma~\ref{MyPrereal.neg_quotient} this is well defined.
\end{definition}

n42222.content:
\begin{definition}
    \label{MyReal.add}
    \lean{MyReal.add}
    \leanok
    \uses{MyReal, MyPrereal.add_quotient}
We define the addition of $⟦ x ⟧$ and $⟦ y ⟧$ in $\mathrm{MyReal}$ as $⟦ x + y ⟧$. Thanks to
Lemma~\ref{MyPrereal.add_quotient} this is well defined.
\end{definition}

n42223.content:
\begin{definition}
    \label{MyReal.mul}
    \lean{MyReal.mul}
    \leanok
    \uses{MyReal, MyPrereal.mul_quotient}
We define the multiplication of $⟦ x ⟧$ and $⟦ y ⟧$ in $\mathrm{MyReal}$ as $⟦ x * y ⟧$. Thanks to
Lemma~\ref{MyPrereal.mul_quotient} this is well defined.
\end{definition}

n42224.content:
\begin{definition}
    \label{MyReal.inv}
    \lean{MyReal.inv}
    \leanok
    \uses{MyReal, MyPrereal.inv_quotient}
We define the inverse of $⟦ x ⟧$ in $\mathrm{MyReal}$ as $⟦ x^{-1} ⟧$. Thanks to
Lemma~\ref{MyPrereal.inv_quotient} this is well defined.
\end{definition}

n42225.content:
\begin{proposition}
    \label{MyReal.commRing}
    \lean{MyReal.commRing}
    \leanok
    $\mathrm{MyReal}$ with addition and multiplication is a commutative ring.
\end{proposition}

n42226.content:
\begin{proof}
    \uses{MyReal.add, MyReal.mul, MyReal.zero, MyReal.one, MyReal.neg}
    \leanok
    All the ring axioms are checked by reducing to representatives and using that the operations are
    termwise, so everything follows from the corresponding properties in $\mathrm{MyRat}$.
\end{proof}

n42228.content:
\begin{proof}
    \leanok
    \uses{MyReal.zero, MyReal.one}
    If $0 = 1$ then the constant sequences $0$ and $1$ would be related, which is false since
    $|0 - 1| = 1$ does not become small.
\end{proof}

n42230.content:
\begin{proof}
    \leanok
    \uses{MyReal.inv, MyReal.mul, MyPrereal.pos_of_not_equiv_zero}
    Let $x = ⟦ a ⟧$ with $a \not\approx 0$. By Lemma~\ref{MyPrereal.pos_of_not_equiv_zero} the terms
    $a_n$ are eventually nonzero, so $a_n a_n^{-1} = 1$ eventually, and hence $a * a^{-1} \approx 1$.
\end{proof}

n42231.content:
\begin{proposition}
    \label{MyReal.field}
    \lean{MyReal.field}
    \leanok
    $\mathrm{MyReal}$ with addition and multiplication is a field.
\end{proposition}

n42232.content:
\begin{proof}
    \uses{MyReal.commRing, MyReal.mul_inv_cancel, MyReal.zero_ne_one}
    \leanok
    Clear because of Lemma~\ref{MyReal.zero_ne_one} and Lemma~\ref{MyReal.mul_inv_cancel}.
\end{proof}

n42233.content:
\begin{definition}
    \label{MyReal.k}
    \lean{MyReal.k}
    \leanok
    \uses{MyReal, MyPrereal.IsCauchy.const}
    We define a map
\begin{gather*}
    k \colon \mathrm{MyRat}\to \mathrm{MyReal}\\
    x \mapsto ⟦ (n \mapsto x) ⟧
\end{gather*}
sending a rational to the class of the corresponding constant sequence.
\end{definition}

n42238.content:
\begin{lemma}
    \label{MyReal.k_neg}
    \lean{MyReal.k_neg}
    \leanok
For all $x$ in $\mathrm{MyRat}$ we have that $k(-x) = -k(x)$.
\end{lemma}

n42240.content:
\begin{lemma}
    \label{MyReal.k_add}
    \lean{MyReal.k_add}
    \leanok
For all $x$ and $y$ in $\mathrm{MyRat}$ we have that $k(x + y) = k(x) + k(y)$.
\end{lemma}

n42242.content:
\begin{lemma}
    \label{MyReal.k_sub}
    \lean{MyReal.k_sub}
    \leanok
For all $x$ and $y$ in $\mathrm{MyRat}$ we have that $k(x - y) = k(x) - k(y)$.
\end{lemma}

n42243.content:
\begin{proof}
    \uses{MyReal.k, MyReal.k_add, MyReal.k_neg}
    \leanok
Clear from the definition.
\end{proof}

n42244.content:
\begin{lemma}
    \label{MyReal.k_mul}
    \lean{MyReal.k_mul}
    \leanok
For all $x$ and $y$ in $\mathrm{MyRat}$ we have that $k(x * y) = k(x) * k(y)$.
\end{lemma}

n42246.content:
\begin{lemma}
    \label{MyReal.k_inv}
    \lean{MyReal.k_inv}
    \leanok
For all $x$ in $\mathrm{MyRat}$ we have that $k(x^{-1}) = k(x)^{-1}$.
\end{lemma}

n42249.content:
\begin{proof}
    \uses{MyReal.k}
    \leanok
    If $k(x) = k(y)$ then the constant sequences $x$ and $y$ are related, so $|x - y|$ is arbitrarily
    small and hence $x = y$.
\end{proof}

n42250.content:
\begin{definition}
    \label{MyPrereal.IsPos}
    \lean{MyPrereal.IsPos}
    \leanok
    \uses{MyPrereal}
Given $x$ in $\mathrm{MyPrereal}$, we say that $x$ is \emph{positive} if there exist $\delta > 0$ and $N$
such that $\delta \leq x_n$ for all $n \geq N$, in other words if $x$ is eventually bounded below by
a positive rational.
\end{definition}

n42251.content:
\begin{lemma}
    \label{MyPrereal.pos_of_isPos}
    \lean{MyPrereal.pos_of_isPos}
    \leanok
    \uses{MyPrereal.IsPos}
    If $x$ is positive, then there exists $N$ such that $0 < x_n$ for all $n \geq N$.
\end{lemma}

n42253.content:
\begin{lemma}
    \label{MyPrereal.one_pos}
    \lean{MyPrereal.one_pos}
    \leanok
    \uses{MyPrereal.IsPos, MyPrereal.one}
    The one of $\mathrm{MyPrereal}$ is positive.
\end{lemma}

n42255.content:
\begin{lemma}
    \label{MyPrereal.not_isPos_zero}
    \lean{MyPrereal.not_isPos_zero}
    \leanok
    \uses{MyPrereal.IsPos, MyPrereal.zero}
    If $x \approx 0$, then $x$ is not positive.
\end{lemma}

n42256.content:
\begin{proof}
    \leanok
    If $x$ were positive its terms would eventually be at least $\delta > 0$, contradicting $x
    \approx 0$.
\end{proof}

n42259.content:
\begin{lemma}
    \label{MyPrereal.isPos_quotient}
    \lean{MyPrereal.isPos_quotient}
    \leanok
    \uses{MyPrereal.IsPos}
    If $x \approx x'$ and $x$ is positive, then $x'$ is positive.
\end{lemma}

n42261.content:
\begin{lemma}
    \label{MyPrereal.IsPos.add}
    \lean{MyPrereal.IsPos.add}
    \leanok
    \uses{MyPrereal.IsPos}
    Let $x$ and $y$ in $\mathrm{MyPrereal}$ both positive. Then $x + y$ is positive.
\end{lemma}

n42263.content:
\begin{lemma}
    \label{MyPrereal.IsPos.mul}
    \lean{MyPrereal.IsPos.mul}
    \leanok
    \uses{MyPrereal.IsPos}
    Let $x$ and $y$ in $\mathrm{MyPrereal}$ both positive. Then $x * y$ is positive.
\end{lemma}

n42265.content:
\begin{definition}
    \label{MyPrereal.IsNonneg}
    \lean{MyPrereal.IsNonneg}
    \leanok
    \uses{MyPrereal.IsPos, MyPrereal.zero}
Given $x$ in $\mathrm{MyPrereal}$, we say that $x$ is \emph{nonnegative} if either $x$ is positive or $x
\approx 0$.
\end{definition}

n42268.content:
\begin{lemma}
    \label{MyPrereal.IsNonneg_of_nonneg}
    \lean{MyPrereal.IsNonneg_of_nonneg}
    \leanok
    \uses{MyPrereal.IsNonneg}
    If there exists $N$ such that $0 \leq x_n$ for all $n \geq N$, then $x$ is nonnegative.
\end{lemma}

n42269.content:
\begin{proof}
    \leanok
    If $x \not\approx 0$ then, by an argument similar to
    Lemma~\ref{MyPrereal.pos_of_not_equiv_zero}, $x$ is eventually bounded below by a positive
    rational, hence positive.
\end{proof}

n42270.content:
\begin{lemma}
    \label{MyPrereal.zero_nonneg}
    \lean{MyPrereal.zero_nonneg}
    \leanok
    \uses{MyPrereal.IsNonneg, MyPrereal.zero}
    The zero of $\mathrm{MyPrereal}$ is nonnegative.
\end{lemma}

n42272.content:
\begin{lemma}
    \label{MyPrereal.one_nonneg}
    \lean{MyPrereal.one_nonneg}
    \leanok
    \uses{MyPrereal.IsNonneg, MyPrereal.one_pos}
    The one of $\mathrm{MyPrereal}$ is nonnegative.
\end{lemma}

n42274.content:
\begin{lemma}
    \label{MyPrereal.isNonneg_quotient}
    \lean{MyPrereal.isNonneg_quotient}
    \leanok
    \uses{MyPrereal.IsNonneg, MyPrereal.isPos_quotient}
    If $x \approx x'$ and $x$ is nonnegative, then $x'$ is nonnegative.
\end{lemma}

n42276.content:
\begin{lemma}
    \label{MyPrereal.eq_zero_of_isNonneg_of_isNonneg_neg}
    \lean{MyPrereal.eq_zero_of_isNonneg_of_isNonneg_neg}
    \leanok
    \uses{MyPrereal.IsNonneg}
    Let $x$ be in $\mathrm{MyPrereal}$ such that both $x$ and $-x$ are nonnegative. Then $x \approx 0$.
\end{lemma}

n42277.content:
\begin{proof}
    \leanok
    \uses{MyPrereal.IsNonneg, MyPrereal.IsPos}
    Suppose $x \not\approx 0$. Since $x$ is nonnegative, $x$ is positive. Since $-x$ is
    nonnegative, either $-x \approx 0$ or $-x$ is positive. The first case implies
    $x \approx 0$, a contradiction. In the second case, $x_n$ and $-x_n$ are both eventually bounded
    below by positive rationals, which is impossible on a common tail. Hence $x \approx 0$.
\end{proof}

n42278.content:
\begin{lemma}
    \label{MyPrereal.isNonneg_neg_of_not_isNonneg}
    \lean{MyPrereal.isNonneg_neg_of_not_isNonneg}
    \leanok
    \uses{MyPrereal.IsNonneg}
    Let $x$ be in $\mathrm{MyPrereal}$ such that $x$ is not nonnegative. Then $-x$ is nonnegative.
\end{lemma}

n42279.content:
\begin{proof}
    \leanok
    If $x$ is not nonnegative then it is in particular not eventually nonnegative, so $-x$ is
    eventually bounded below by a positive rational.
\end{proof}

n42280.content:
\begin{definition}
    \label{MyReal.IsNonneg}
    \lean{MyReal.IsNonneg}
    \leanok
    \uses{MyPrereal.IsNonneg, MyPrereal.isNonneg_quotient}
We say that $⟦ x ⟧$ in $\mathrm{MyReal}$ is \emph{nonnegative} if $x$ is nonnegative. Thanks to
Lemma~\ref{MyPrereal.isNonneg_quotient} this does not depend on the representative.
\end{definition}

n42281.content:
\begin{lemma}
    \label{MyReal.zero_nonneg}
    \lean{MyReal.zero_nonneg}
    \leanok
    \uses{MyReal.IsNonneg, MyReal.zero, MyPrereal.zero_nonneg}
    The zero of $\mathrm{MyReal}$ is nonnegative.
\end{lemma}

n42283.content:
\begin{lemma}
    \label{MyReal.eq_zero_of_isNonneg_of_isNonneg_neg}
    \lean{MyReal.eq_zero_of_isNonneg_of_isNonneg_neg}
    \leanok
    \uses{MyReal.IsNonneg, MyPrereal.eq_zero_of_isNonneg_of_isNonneg_neg}
    Let $x$ be in $\mathrm{MyReal}$ such that both $x$ and $-x$ are nonnegative. Then $x = 0$.
\end{lemma}

n42285.content:
\begin{lemma}
    \label{MyReal.IsNonneg.add}
    \lean{MyReal.IsNonneg.add}
    \leanok
    \uses{MyReal.IsNonneg, MyPrereal.IsPos.add}
    Let $x$ and $y$ in $\mathrm{MyReal}$ both nonnegative. Then $x + y$ is nonnegative.
