n42286.content:
\begin{proof}
    \leanok
    Reduce to representatives and use Lemma~\ref{MyPrereal.IsPos.add} (treating the cases where one
    of them is $\approx 0$ separately).
\end{proof}

n42287.content:
\begin{lemma}
    \label{MyReal.IsNonneg.mul}
    \lean{MyReal.IsNonneg.mul}
    \leanok
    \uses{MyReal.IsNonneg, MyPrereal.IsPos.mul}
    Let $x$ and $y$ in $\mathrm{MyReal}$ both nonnegative. Then $x * y$ is nonnegative.
\end{lemma}

n42288.content:
\begin{proof}
    \leanok
    Reduce to representatives and use Lemma~\ref{MyPrereal.IsPos.mul}.
\end{proof}

n42289.content:
\begin{definition}
    \label{MyReal.le}
    \lean{MyReal.le}
    \leanok
    \uses{MyReal.IsNonneg, MyReal.field}
Let $x$ and $y$ in $\mathrm{MyReal}$. We write $x \leq y$ if $y - x$ is nonnegative.
\end{definition}

n42290.content:
\begin{lemma}
    \label{MyReal.zero_le_iff_isNonneg}
    \lean{MyReal.zero_le_iff_isNonneg}
    \leanok
    \uses{MyReal.zero, MyReal.le}
    We have that $0 \leq x$ if and only if $x$ is nonnegative.
\end{lemma}

n42293.content:
\begin{proof}
    \uses{MyReal.zero, MyReal.one, MyPrereal.one_nonneg}
    \leanok
    Clear because of Lemma~\ref{MyPrereal.one_nonneg}.
\end{proof}

n42297.content:
\begin{proof}
    \uses{MyReal.le, MyReal.IsNonneg.add}
    \leanok
    It follows from Lemma~\ref{MyReal.IsNonneg.add}, since $(z - y) + (y - x) = z - x$.
\end{proof}

n42300.content:
\begin{lemma}
    \label{MyReal.add_le_add_left}
    \lean{MyReal.add_le_add_left}
    \leanok
    Let $x$, $y$ and $t$ in $\mathrm{MyReal}$ be such that $x \leq y$. Then $x + t \leq y + t$.
\end{lemma}

n42301.content:
\begin{proof}
    \uses{MyReal.le, MyReal.add}
    \leanok
    Clear from the definitions, since $(y + t) - (x + t) = y - x$.
\end{proof}

n42302.content:
\begin{lemma}
    \label{MyReal.mul_nonneg}
    \lean{MyReal.mul_nonneg}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyReal}$ be such that $0 \leq x$ and $0 \leq y$. Then $0 \leq x * y$.
\end{lemma}

n42304.content:
\begin{lemma}
    \label{MyReal.k_le_iff}
    \lean{MyReal.k_le_iff}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyRat}$. We have that $k(x) \leq k(y)$ if and only if $x \leq y$.
\end{lemma}

n42306.content:
\begin{lemma}
    \label{MyReal.k_lt_iff}
    \lean{MyReal.k_lt_iff}
    \leanok
    Let $x$ and $y$ in $\mathrm{MyRat}$. We have that $k(x) < k(y)$ if and only if $x < y$.
\end{lemma}

n42307.content:
\begin{proof}
    \uses{MyReal.k_le_iff, MyReal.k_injective}
    \leanok
    Immediate from Lemma~\ref{MyReal.k_le_iff} and Lemma~\ref{MyReal.k_injective}.
\end{proof}

n42308.content:
\begin{lemma}
    \label{MyReal.le_total}
    \lean{MyReal.le_total}
    \leanok
    The order $\leq$ on $\mathrm{MyReal}$ is a total order.
\end{lemma}

n42310.content:
\begin{lemma}
    \label{MyReal.linearOrder}
    \lean{MyReal.linearOrder}
    \leanok
    We have that $\mathrm{MyReal}$ with $\leq$ is a \emph{linear order}.
\end{lemma}

n42311.content:
\begin{proof}
    \uses{MyReal.le_refl, MyReal.le_antisymm, MyReal.le_trans, MyReal.le_total}
    \leanok
    Clear from the lemmas above.
\end{proof}

n42312.content:
\begin{lemma}
    \label{MyReal.mul_pos}
    \lean{MyReal.mul_pos}
    \leanok
    Let $a$ and $b$ in $\mathrm{MyReal}$ be such that $0 < a$ and $0 < b$. Then $0 < a * b$.
\end{lemma}

n42313.content:
\begin{proof}
    \leanok
    \uses{MyReal.zero_le_iff_isNonneg, MyPrereal.IsPos.mul}
Exercise, using that a positive real is the class of a positive prereal and
Lemma~\ref{MyPrereal.IsPos.mul}.
\end{proof}

n42314.content:
\begin{lemma}
    \label{MyReal.myRat_dense_rat'}
    \lean{MyReal.myRat_dense_rat'}
    \leanok
    \uses{MyReal.k}
    Let $x$ in $\mathrm{MyReal}$ and let $\varepsilon$ in $\mathrm{MyRat}$ with $0 < \varepsilon$. Then there exists
    $r$ in $\mathrm{MyRat}$ with $|x - k(r)| < k(\varepsilon)$.
\end{lemma}

n42315.content:
\begin{proof}
    \leanok
    Pick a representative $a$ of $x$; by the Cauchy property the rational $r = a_N$ for $N$ large
    enough works.
\end{proof}

n42316.content:
\begin{lemma}
    \label{MyReal.myRat_dense_of_pos}
    \lean{MyReal.myRat_dense_of_pos}
    \leanok
    \uses{MyReal.k, MyReal.k_lt_iff}
    Let $x$ in $\mathrm{MyReal}$ with $0 < x$. Then there exists $r$ in $\mathrm{MyRat}$ with $0 < r$ and $k(r) < x$.
\end{lemma}

n42317.content:
\begin{proof}
    \leanok
    A positive real is the class of a positive prereal, which is eventually bounded below by a
    positive rational $r$.
\end{proof}

n42318.content:
\begin{lemma}
    \label{MyReal.myRat_dense_rat}
    \lean{MyReal.myRat_dense_rat}
    \leanok
    \uses{MyReal.myRat_dense_rat', MyReal.myRat_dense_of_pos}
    Let $x$ in $\mathrm{MyReal}$ and let $\varepsilon$ in $\mathrm{MyReal}$ with $0 < \varepsilon$. Then there exists
    $r$ in $\mathrm{MyRat}$ with $|x - k(r)| < \varepsilon$.
\end{lemma}

n42319.content:
\begin{proof}
    \leanok
    Combine Lemma~\ref{MyReal.myRat_dense_of_pos} (to find a rational below $\varepsilon$) with
    Lemma~\ref{MyReal.myRat_dense_rat'}.
\end{proof}

n42320.content:
\begin{definition}
    \label{MyReal.TendsTo}
    \lean{MyReal.TendsTo}
    \leanok
    \uses{MyReal.le}
A sequence $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ \emph{tends to} $x$ in $\mathrm{MyReal}$ if
\[
\forall \varepsilon > 0, \ \exists N, \ \forall n \geq N, \ |f_n - x| \leq \varepsilon.
\]
\end{definition}

n42321.content:
\begin{definition}
    \label{MyReal.IsConvergent}
    \lean{MyReal.IsConvergent}
    \leanok
    \uses{MyReal.TendsTo}
A sequence $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ is \emph{convergent} if it tends to some $x$ in $\mathrm{MyReal}$.
\end{definition}

n42322.content:
\begin{definition}
    \label{MyReal.IsCauchy}
    \lean{MyReal.IsCauchy}
    \leanok
    \uses{MyReal.le}
A sequence $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ is a \emph{Cauchy sequence} if
\[
\forall \varepsilon > 0, \ \exists N, \ \forall p, q \geq N, \ |f_p - f_q| \leq \varepsilon.
\]
\end{definition}

n42323.content:
\begin{lemma}
    \label{MyReal.tendsTo_of_myRat_tendsTo}
    \lean{MyReal.tendsTo_of_myRat_tendsTo}
    \leanok
    \uses{MyReal.TendsTo, MyReal.k}
    Let $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ and $x$ in $\mathrm{MyReal}$. If for every rational $\varepsilon > 0$
    there exists $N$ such that $|f_n - x| \leq k(\varepsilon)$ for all $n \geq N$, then $f$ tends to
    $x$.
\end{lemma}

n42324.content:
\begin{proof}
    \leanok
    \uses{MyReal.myRat_dense_of_pos}
    It is enough to check the condition for $\varepsilon$ of the form $k(\delta)$, which is possible
    by density (Lemma~\ref{MyReal.myRat_dense_of_pos}).
\end{proof}

n42325.content:
\begin{lemma}
    \label{MyReal.tendsTo_myRat}
    \lean{MyReal.tendsTo_myRat}
    \leanok
    \uses{MyReal.TendsTo, MyReal.k}
    Let $x$ in $\mathrm{MyPrereal}$. Then the sequence $n \mapsto k(x_n)$ tends to $⟦ x ⟧$.
\end{lemma}

n42326.content:
\begin{proof}
    \leanok
    \uses{MyReal.tendsTo_of_myRat_tendsTo}
    Immediate from the definition of $\approx$ and Lemma~\ref{MyReal.tendsTo_of_myRat_tendsTo}: the
    Cauchy property of $x$ is exactly what is needed.
\end{proof}

n42327.content:
\begin{lemma}
    \label{MyReal.archimedean}
    \lean{MyReal.archimedean}
    \leanok
    \uses{MyReal.k, MyRat.i, MyReal.myRat_dense_rat, MyRat.archimedean, MyReal.k_le_iff}
    Let $x$ in $\mathrm{MyReal}$. Then there exists a natural number $n$ such that $x \leq k(i(n+1))$, where
    $i \colon \mathrm{MyNat}\to \mathrm{MyRat}$ is the inclusion.
\end{lemma}

n42328.content:
\begin{proof}
    \leanok
    Apply density with $\varepsilon = 1$ to find $r$ with $|x-k(r)|<1$, so $x<k(r+1)$.
    Then use Lemma~\ref{MyRat.archimedean} to bound $r+1$ by some $i(m)$, enlarge this to a bound
    of the form $i(n+1)$, and transfer the inequality through $k$.
\end{proof}

n42329.content:
\begin{lemma}
    \label{MyReal.archimedean0}
    \lean{MyReal.archimedean0}
    \leanok
    \uses{MyReal.archimedean}
    Let $x$ in $\mathrm{MyReal}$ with $0 < x$. Then there exists a natural number $n$ such that
    $k(i(n+1)^{-1}) \leq x$.
\end{lemma}

n42330.content:
\begin{proof}
    \leanok
    Apply Lemma~\ref{MyReal.archimedean} to $x^{-1}$ and take inverses.
\end{proof}

n42331.content:
\begin{lemma}
    \label{MyReal.ex_approx_punctual}
    \lean{MyReal.ex_approx_punctual}
    \leanok
    \uses{MyReal.k, MyRat.i}
    Let $x$ in $\mathrm{MyReal}$ and $n$ a natural number. Then there exists a rational $r$ such that
    $|x - k(r)| < k(i(n+1)^{-1})$.
\end{lemma}

n42333.content:
\begin{lemma}
    \label{MyReal.ex_approx}
    \lean{MyReal.ex_approx}
    \leanok
    \uses{MyReal.ex_approx_punctual}
    Let $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$. Then there exists $g \colon \mathrm{MyNat}\to \mathrm{MyRat}$ such that
    $|f_n - k(g_n)| < k(i(n+1)^{-1})$ for all $n$.
\end{lemma}

n42334.content:
\begin{proof}
    \leanok
    Apply Lemma~\ref{MyReal.ex_approx_punctual} for each $n$ and collect the choices.
\end{proof}

n42335.content:
\begin{definition}
    \label{MyReal.approx}
    \lean{MyReal.approx}
    \leanok
    \uses{MyReal.ex_approx}
    Given $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$, we define $\mathrm{approx}(f) \colon \mathrm{MyNat}\to \mathrm{MyRat}$ to
    be a choice of rational approximating sequence as in Lemma~\ref{MyReal.ex_approx}.
\end{definition}

n42336.content:
\begin{lemma}
    \label{MyReal.approx_spec}
    \lean{MyReal.approx_spec}
    \leanok
    \uses{MyReal.approx}
    For all $n$ we have $|f_n - k(\mathrm{approx}(f)_n)| < k(i(n+1)^{-1})$.
\end{lemma}

n42337.content:
\begin{proof}
    \leanok
    This is the defining property of $\mathrm{approx}(f)$.
\end{proof}

n42338.content:
\begin{lemma}
    \label{MyReal.approx_cauchy}
    \lean{MyReal.approx_cauchy}
    \leanok
    \uses{MyReal.approx_spec, IsCauchy, MyReal.IsCauchy}
    If $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ is a Cauchy sequence, then $\mathrm{approx}(f)$ is a Cauchy
    sequence of rationals.
\end{lemma}

n42339.content:
\begin{proof}
    \leanok
    \uses{MyReal.archimedean0}
    Estimate $|\mathrm{approx}(f)_p - \mathrm{approx}(f)_q|$ by inserting $f_p$ and $f_q$ and using
    Lemma~\ref{MyReal.approx_spec}, together with the archimedean property
    (Lemma~\ref{MyReal.archimedean0}) to make the error terms small.
\end{proof}

n42340.content:
\begin{definition}
    \label{MyReal.IsCauchy.approx}
    \lean{MyReal.IsCauchy.approx}
    \leanok
    \uses{MyReal.approx_cauchy, MyPrereal}
    If $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ is a Cauchy sequence, then $\mathrm{approx}(f)$, being a Cauchy
    sequence of rationals, defines an element of $\mathrm{MyPrereal}$.
\end{definition}

n42341.content:
\begin{theorem}
    \label{MyReal.complete}
    \lean{MyReal.complete}
    \leanok
    $\mathrm{MyReal}$ is complete: every Cauchy sequence $f \colon \mathrm{MyNat}\to \mathrm{MyReal}$ is convergent.
\end{theorem}

n42342.content:
\begin{proof}
    \leanok
    \uses{MyReal.IsCauchy.approx, MyReal.tendsTo_myRat, MyReal.approx_spec, MyReal.IsConvergent}
    Let $a = \mathrm{approx}(f)$, seen as an element of $\mathrm{MyPrereal}$
    (Definition~\ref{MyReal.IsCauchy.approx}), and let $x = ⟦ a ⟧$. By
    Lemma~\ref{MyReal.tendsTo_myRat} the sequence $n \mapsto k(a_n)$ tends to $x$, and by
    Lemma~\ref{MyReal.approx_spec} the sequence $f$ stays close to $n \mapsto k(a_n)$, so $f$ tends
    to $x$. Hence $f$ is convergent.
\end{proof}
